using System;using System.Collections.Generic;using Exoduser.UnityPort.Core.Combat;using Exoduser.UnityPort.Core.Skills;
namespace Exoduser.UnityPort.Core {
 public sealed partial class Simulation {
  static double ZoneDistance(double x,double y,double xx,double yy){double dx=x-xx,dy=y-yy;return Math.Sqrt(dx*dx+dy*dy);}
  sealed class QueuedPillar {public FireZone Zone;public int Delay;}
  readonly List<QueuedPillar> pillarQueue=new List<QueuedPillar>();readonly HashSet<EnemyState> pillarHitThisFrame=new HashSet<EnemyState>();int pillarQueueTime;
  public float DarkPillarCd,HolyPrisonCd,MaliceDomeCd;public int? IceStormStocks;public int IceStormRecharge;public bool IceStormAiming;bool skillAimConfirm,skillAimCancel;
  public void SetSkillAimInput(bool confirm,bool cancel){skillAimConfirm|=confirm;skillAimCancel|=cancel;}
  bool CastDarkPillar(){if(DarkPillarCd>0){DenySkill("darkPillar","cooldown");return false;}int lv=Math.Max(1,Skills.Level("darkPillar"));float radius=250+(lv-1)*22;double damage=Js.Int(MagicReference()*MagicDamageMultiplier()*SkillRules.SkMul("darkPillar",lv));bool spike=Skills.Fused.Contains("pillarSpike")&&Skills.Learned("spikeTrap");var positions=new List<float[]>{new[]{Player.X,Player.Y}};for(int ring=0;ring<2;ring++)for(int i=0;i<4;i++){double a=Math.PI*2*i/4,range=radius*(ring==0?.3:.75);positions.Add(new[]{Player.X+(float)(Math.Cos(a)*range),Player.Y+(float)(Math.Sin(a)*range)});}for(int i=0;i<positions.Count;i++){var p=positions[i];var zone=new FireZone{Id=nextZoneId++,Type="darkPillar",Element=3,X=p[0],Y=p[1],R=radius*.5f,T=0,MaxT=600,Lv=lv,Dmg=damage,PillarSpike=spike};if(i==0)FireZones.Add(zone);else pillarQueue.Add(new QueuedPillar{Zone=zone,Delay=i*10});}pillarQueueTime=0;DarkPillarCd=Js.Int(900*(1+CooldownReduction));if(spike){int slv=Math.Max(1,Skills.Level("spikeTrap"));for(int i=0;i<Math.Min(5,positions.Count);i++)FireZones.Add(new FireZone{Id=nextZoneId++,Type="spikeTrap",X=positions[i][0],Y=positions[i][1],R=250+(slv-1)*15,MaxT=600,Lv=slv,Dmg=SkillRules.SpikeTrapDamage(MagicReference(),1,MagicDamageMultiplier(),slv),PillarSpike=true});SpikeTrapCd=Js.Int(600*(1+CooldownReduction));}SkillSample("voice_dark_skill",1,1);HurtShake(5);Cast("darkPillar");return true;}
  bool CastHolyPrison(){if(HolyPrisonCd>0){DenySkill("holyPrison","cooldown");return false;}int lv=Math.Max(1,Skills.Level("holyPrison"));HolyPrisonCd=1800;FireZones.Add(new FireZone{Id=nextZoneId++,Type="holyPrison",X=Player.X,Y=Player.Y,R=400+(lv-1)*33,MaxT=600+lv*30,Lv=lv});HolyPrisonSuppress=HolyPrisonAt;SkillSample("voice_holyPrison",1,1);HurtShake(4);Cast("holyPrison");return true;}
  public double HolyPrisonAt(double x,double y){foreach(var z in FireZones)if(z.Type=="holyPrison"&&ZoneDistance(x,y,z.X,z.Y)<z.R)return .15+(Math.Max(1,z.Lv)-1)*(.15/9);return double.NaN;}
  bool CastMaliceDome(){if(MaliceDomeCd>0||Player.Mana<60){DenySkill("maliceDome",MaliceDomeCd>0?"cooldown":"mana");return false;}int lv=Math.Max(1,Skills.Level("maliceDome"));Player.Mana=Math.Max(0,Player.Mana-60);MaliceDomeCd=1500;FireZones.Add(new FireZone{Id=nextZoneId++,Type="maliceDome",X=Player.X,Y=Player.Y,R=300+lv*15,MaxT=480+lv*30,Lv=lv});HurtShake(4);Cast("maliceDome");return true;}
  bool MaliceDomeAbsorbs(BossProjectile p){if(p.Friendly||p.Mine)return false;foreach(var z in FireZones)if(z.Type=="maliceDome"&&ZoneDistance(z.X,z.Y,p.X,p.Y)<z.R)return true;return false;}
  bool BeginIceStormAim(){if(IceStormAiming){IceStormAiming=false;return false;}if(!IceStormStocks.HasValue)IceStormStocks=Skills.Level("iceStorm")>=10?3:2;if(IceStormStocks<=0||Player.Mana<40){DenySkill("iceStorm",IceStormStocks<=0?"stock":"mana");return false;}IceStormAiming=true;return true;}
  void TickExtendedSkillPreparation(float aimX,float aimY){TickBladeSkillPreparation(aimX,aimY);pillarHitThisFrame.Clear();if(pillarQueue.Count>0){pillarQueueTime++;for(int i=0;i<pillarQueue.Count;i++)if(pillarQueueTime>=pillarQueue[i].Delay){FireZones.Add(pillarQueue[i].Zone);pillarQueue.RemoveAt(i--);HurtShake(2);}}
   if(DarkPillarCd>0)DarkPillarCd--;if(HolyPrisonCd>0)HolyPrisonCd--;if(MaliceDomeCd>0){float bonus=0;foreach(var z in FireZones)if(z.Type=="holyDome"&&ZoneDistance(Player.X,Player.Y,z.X,z.Y)<z.R){bonus=1;break;}MaliceDomeCd-=1+bonus;}
   if(Skills.Learned("iceStorm")){int max=Skills.Level("iceStorm")>=10?3:2;if(!IceStormStocks.HasValue)IceStormStocks=max;if(IceStormStocks<max){if(IceStormRecharge==0)IceStormRecharge=1500;IceStormRecharge--;if(IceStormRecharge<=0){IceStormStocks=Math.Min(max,IceStormStocks.Value+1);IceStormRecharge=IceStormStocks<max?1500:0;}}}
   if(IceStormAiming){if(skillAimCancel)IceStormAiming=false;else if(skillAimConfirm){int lv=Math.Max(1,Skills.Level("iceStorm"));float x=aimX,y=aimY;double d=ZoneDistance(Player.X,Player.Y,x,y);if(d>1000){double a=Math.Atan2(y-Player.Y,x-Player.X);x=Player.X+(float)(Math.Cos(a)*1000);y=Player.Y+(float)(Math.Sin(a)*1000);}float radius=400+(lv-1)*18;bool blocked=false;foreach(var z in FireZones)if(z.Type=="iceStorm"&&ZoneDistance(x,y,z.X,z.Y)<z.R+radius){blocked=true;break;}if(IceStormStocks<=0)IceStormAiming=false;else if(Player.Mana>=40&&!blocked){Player.Mana=Math.Max(0,Player.Mana-40);FireZones.Add(new FireZone{Id=nextZoneId++,Type="iceStorm",Element=2,X=x,Y=y,R=radius,MaxT=600,Lv=lv});IceStormStocks--;int max=lv>=10?3:2;if(IceStormStocks<max&&IceStormRecharge==0)IceStormRecharge=1500;IceStormAiming=false;SkillSample("ice_storm",.7,1);SkillSample("voice_magic",1,1);HurtShake(4);Cast("iceStorm");}}}skillAimConfirm=skillAimCancel=false;
  }
  bool TickExtendedZone(FireZone z){if(z.Type=="holyPrison")return true;if(z.Type=="maliceDome"){if(z.T>=z.MaxT)return true;foreach(var e in Enemies.ToArray()){if(!e.Alive||e.IsBoss||ZoneDistance(e.X,e.Y,z.X,z.Y)>=z.R)continue;double a=Math.Atan2(e.Y-z.Y,e.X-z.X);e.X=z.X+(float)(Math.Cos(a)*(z.R+8));e.Y=z.Y+(float)(Math.Sin(a)*(z.R+8));e.KnockbackX=(float)(Math.Cos(a)*6);e.KnockbackY=(float)(Math.Sin(a)*6);var w=SyncToWeb(e);w.vx=w.vy=0;}return true;}if(z.Type=="iceStorm"){z.TickTimer++;if(z.TickTimer>=6){z.TickTimer=0;foreach(var e in Enemies.ToArray()){if(!e.Alive||ZoneDistance(e.X,e.Y,z.X,z.Y)>z.R)continue;var w=SyncToWeb(e);w._iceResDown=Math.Max(w._iceResDown??0,30);if((w._frozen??0)<=0&&(w._frozenImmune??0)<=0){if(!(w._freezeMax>0))w._freezeMax=w.ib?500:100;if(!(w._freezeGauge>0))w._freezeGauge=0;w._freezeGauge=Math.Min(w._freezeMax.Value,w._freezeGauge.Value+(w.ib?15+z.Lv*2:35+z.Lv*4));if(w._freezeGauge>=w._freezeMax){w._frozen=180;w._freezeGauge=0;}}w._webSlow=Math.Max(w._webSlow??0,25);w.flashT=4;}}return true;}if(z.Type=="darkPillar"){z.TickTimer++;if(z.TickTimer>=30){z.TickTimer-=30;foreach(var e in Enemies.ToArray()){if(!e.Alive||ZoneDistance(e.X,e.Y,z.X,z.Y)>z.R||!pillarHitThisFrame.Add(e))continue;ApplyEnemyDamage(e,z.Dmg,(float)Math.Atan2(e.Y-z.Y,e.X-z.X),false,1,true,true,0,0,false,z.Element);var w=e.Web??SyncToWeb(e);w._webSlow=Math.Max(w._webSlow??0,25);}}return true;}return false;}
 }
}
